    if c.store.len() >= c.max_size {
      return false;
    };
    c.store.push(item);
    true
  }

  pub fn lookup(c: &CacheData, item: Str) -> Bool {
    let mut i = 0;
    while i < c.store.len() {
      if c.store.get(i).unwrap() == item {
        return true;
      };
      i += 1;
    };
    false
  }

  pub fn size(c: &CacheData) -> Int {
    c.store.len()
  }
}

